import{_ as t,o as a,c as s,ae as i}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Registry Manifest and Status Command","description":"","frontmatter":{"work_package_id":"WP01","title":"Registry Manifest and Status Command","lane":"done","dependencies":[],"base_branch":"main","base_commit":"9552558a2d3333de47ddae58d65bd41ebc2b6f85","created_at":"2026-03-01T13:29:44.943436+00:00","subtasks":["T001","T002","T003","T004","T005"],"phase":"Phase 1 - Dependency Tracking","assignee":"","agent":"claude-haiku","shell_pid":"55021","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/020-prerelease-dependency-registry/tasks/WP01-registry-manifest-and-status-command.md","filePath":"specs/020-prerelease-dependency-registry/tasks/WP01-registry-manifest-and-status-command.md"}'),l={name:"specs/020-prerelease-dependency-registry/tasks/WP01-registry-manifest-and-status-command.md"};function o(r,e,n,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="work-package-prompt-wp01-registry-manifest-and-status-command" tabindex="-1">Work Package Prompt: WP01 - Registry Manifest and Status Command <a class="header-anchor" href="#work-package-prompt-wp01-registry-manifest-and-status-command" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Registry Manifest and Status Command&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Create a version-controlled registry manifest that tracks all prerelease dependencies with rich metadata.</li><li>Deliver a <code>bun run deps:status</code> command for visibility into current pins, available upgrades, and staleness.</li><li>Establish a structured changelog for all upgrade attempts.</li></ul><p>Success criteria:</p><ul><li>The manifest contains entries for all tracked prerelease dependencies with complete metadata.</li><li><code>bun run deps:status</code> reports accurate current pins, latest versions, channels, and days since last update.</li><li>The changelog schema supports recording pass/fail upgrade attempts with full context.</li><li>All manifest and changelog operations are tested.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/020-prerelease-dependency-registry/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/020-prerelease-dependency-registry/spec.md</code></li></ul><p>Constraints:</p><ul><li>Manifest must be version-controlled in the repo (NFR-004).</li><li>Status command must complete in &lt; 10 seconds with warm cache (NFR-002).</li><li>Manifest changes must be committed atomically with lockfile changes.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-create-deps-registry-json-manifest-schema" tabindex="-1">Subtask T001 - Create deps-registry.json manifest schema <a class="header-anchor" href="#subtask-t001-create-deps-registry-json-manifest-schema" aria-label="Permalink to &quot;Subtask T001 - Create deps-registry.json manifest schema&quot;">​</a></h3><ul><li>Purpose: Define the structured format for tracking prerelease dependencies with all metadata needed for safe upgrade management.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/deps-registry.json</code> with a well-defined JSON schema.</li><li>Each dependency entry must include: <code>name</code> (package identifier), <code>currentPin</code> (exact version string), <code>channel</code> (one of: <code>alpha</code>, <code>beta</code>, <code>rc</code>, <code>stable</code>), <code>upstreamSource</code> (registry URL or GitHub release URL), <code>knownGoodHistory</code> (array of <code>{version, timestamp, gateResult}</code> objects), and <code>lastUpdated</code> (ISO 8601 timestamp).</li><li>Include a top-level <code>schemaVersion</code> field for future schema evolution.</li><li>Include a <code>metadata</code> section with <code>lastStatusCheck</code> timestamp and <code>registryCacheMaxAge</code> duration.</li><li>Validate the schema is parseable by standard JSON tools and TypeScript type-safe.</li><li>Define a TypeScript interface in <code>scripts/deps-types.ts</code> matching the JSON schema for compile-time safety.</li><li>Add JSDoc comments to all interface fields documenting their purpose and constraints.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/deps-registry.json</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-types.ts</code></li></ul></li><li>Acceptance: <ul><li>JSON schema is valid and parseable.</li><li>TypeScript interfaces match JSON structure exactly.</li><li>All fields documented with JSDoc.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-populate-initial-manifest-entries" tabindex="-1">Subtask T002 - Populate initial manifest entries <a class="header-anchor" href="#subtask-t002-populate-initial-manifest-entries" aria-label="Permalink to &quot;Subtask T002 - Populate initial manifest entries&quot;">​</a></h3><ul><li>Purpose: Seed the manifest with the project&#39;s known prerelease dependencies so the status command has real data to report from day one.</li><li>Steps: <ol><li>Identify all prerelease dependencies currently used in the project: ElectroBun, ghostty, zellij, and any others referenced in <code>package.json</code> or <code>bunfig.toml</code>.</li><li>For each dependency, determine: current pinned version, channel designation, upstream source URL (npm registry or GitHub releases API endpoint).</li><li>Add each entry to <code>deps-registry.json</code> with an initial <code>knownGoodHistory</code> containing the current pin as the first known-good version.</li><li>Set <code>lastUpdated</code> to the current timestamp.</li><li>Verify the populated manifest parses correctly using the TypeScript interface from T001.</li><li>Commit the manifest alongside the lockfile to establish the initial tracking baseline.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/deps-registry.json</code></li></ul></li><li>Acceptance: <ul><li>All known prerelease dependencies have manifest entries.</li><li>Each entry has a complete and accurate set of fields.</li><li>The manifest is valid JSON parseable by the TypeScript types.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-deps-status-command" tabindex="-1">Subtask T003 - Implement deps:status command <a class="header-anchor" href="#subtask-t003-implement-deps-status-command" aria-label="Permalink to &quot;Subtask T003 - Implement deps:status command&quot;">​</a></h3><ul><li>Purpose: Give developers and CI a single command to see the health of all tracked prerelease dependencies.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-status.ts</code>.</li><li>Read and parse <code>deps-registry.json</code> using the TypeScript interfaces from T001.</li><li>For each tracked dependency, query the upstream source for the latest available version: <ul><li>For npm packages: use <code>npm view &lt;package&gt; versions --json</code> or Bun&#39;s equivalent.</li><li>For GitHub releases: use the GitHub Releases API (<code>GET /repos/{owner}/{repo}/releases</code>).</li></ul></li><li>Implement a local response cache (file-based or in-memory) to avoid hitting rate limits. Cache TTL should be configurable via <code>metadata.registryCacheMaxAge</code> in the manifest.</li><li>Calculate <code>daysSinceLastUpdate</code> for each dependency based on <code>lastUpdated</code>.</li><li>Format output as a table with columns: Package, Current Pin, Latest Available, Channel, Days Since Update, Status (up-to-date/upgrade-available/stale).</li><li>Add <code>--json</code> flag for structured JSON output suitable for CI consumption.</li><li>Exit 0 if all dependencies are up-to-date; exit 1 if any have available upgrades; exit 2 on registry errors.</li><li>Add the <code>deps:status</code> script entry to root <code>package.json</code>.</li><li>Handle edge cases: registry unreachable (warn and use cached data), dependency channel disappeared (alert), malformed manifest entry (error with specific field).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-status.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (script entry)</li></ul></li><li>Acceptance: <ul><li><code>bun run deps:status</code> produces a readable table of all tracked dependencies.</li><li><code>--json</code> flag produces structured JSON output.</li><li>Completes in &lt; 10 seconds with warm cache.</li><li>Graceful degradation on registry failures.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-create-changelog-schema-and-append-utility" tabindex="-1">Subtask T004 - Create changelog schema and append utility <a class="header-anchor" href="#subtask-t004-create-changelog-schema-and-append-utility" aria-label="Permalink to &quot;Subtask T004 - Create changelog schema and append utility&quot;">​</a></h3><ul><li>Purpose: Establish a structured, append-only log of all dependency upgrade attempts for auditability.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/deps-changelog.json</code> with an initial empty array.</li><li>Define the changelog entry schema in <code>scripts/deps-types.ts</code>: <code>timestamp</code> (ISO 8601), <code>package</code> (name), <code>fromVersion</code>, <code>toVersion</code>, <code>channel</code>, <code>gateResults</code> (object with per-gate pass/fail), <code>outcome</code> (success/failure/rollback), <code>actor</code> (user/ci/canary), <code>branchRef</code> (optional, for canary runs).</li><li>Implement an <code>appendChangelogEntry</code> function in a shared utility (<code>scripts/deps-changelog-util.ts</code>) that: <ul><li>Reads the current changelog.</li><li>Validates the new entry against the schema.</li><li>Appends the entry.</li><li>Writes the file atomically (write to temp, rename).</li></ul></li><li>Ensure the utility is importable by both the rollback and canary scripts (WP02).</li><li>Add the changelog file to version control alongside the manifest.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/deps-changelog.json</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-types.ts</code> (changelog entry interface)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-changelog-util.ts</code></li></ul></li><li>Acceptance: <ul><li>Changelog entries are appended atomically.</li><li>Schema validation prevents malformed entries.</li><li>The utility is reusable by rollback and canary scripts.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t005-add-unit-tests-for-manifest-status-and-changelog" tabindex="-1">Subtask T005 - Add unit tests for manifest, status, and changelog <a class="header-anchor" href="#subtask-t005-add-unit-tests-for-manifest-status-and-changelog" aria-label="Permalink to &quot;Subtask T005 - Add unit tests for manifest, status, and changelog&quot;">​</a></h3><ul><li>Purpose: Lock the behavior of the manifest parser, status reporter, and changelog utility with deterministic tests.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-manifest.test.ts</code>: <ul><li>Test: valid manifest parses without errors.</li><li>Test: manifest with missing required fields throws with specific field name.</li><li>Test: manifest with invalid channel value throws.</li><li>Test: known-good history is ordered chronologically.</li></ul></li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-status.test.ts</code>: <ul><li>Test: status command produces correct table output for known fixture data.</li><li>Test: <code>--json</code> flag produces valid JSON matching expected schema.</li><li>Test: registry cache is used when available and fresh.</li><li>Test: stale cache triggers re-fetch.</li><li>Test: unreachable registry falls back to cached data with warning.</li></ul></li><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-changelog.test.ts</code>: <ul><li>Test: valid entry appends successfully.</li><li>Test: invalid entry (missing field) is rejected.</li><li>Test: concurrent appends produce consistent results (no data loss).</li><li>Test: atomic write prevents partial file corruption.</li></ul></li><li>Ensure all tests run via <code>bun test scripts/tests/</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-manifest.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-status.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-changelog.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All tests pass.</li><li>Tests cover positive, negative, and edge cases.</li><li>Tests are deterministic (no flakiness).</li></ul></li><li>Parallel: Yes (after T003 and T004 interfaces are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Vitest unit tests for manifest parsing, status reporting, and changelog operations.</li><li>Fixture-based tests with known-good and malformed data.</li><li>Cache behavior tests with mocked registry responses.</li><li>Deterministic, no flakiness.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Upstream registry API changes break status queries.</li><li>Mitigation: Abstract registry access behind an adapter interface; mock in tests.</li><li>Risk: Manifest schema needs to evolve.</li><li>Mitigation: <code>schemaVersion</code> field enables forward-compatible evolution.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm all manifest fields are documented and type-safe.</li><li>Confirm status command handles registry failures gracefully.</li><li>Confirm changelog writes are atomic and validated.</li><li>Confirm no suppression directives in any source file.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:29:45Z – claude-haiku – shell_pid=55021 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:31:39Z – claude-haiku – shell_pid=55021 – lane=done – Implemented</li></ul>',30)])])}const m=t(l,[["render",o]]);export{h as __pageData,m as default};
